-- QA ONLY / WRITTEN, NOT_RUN. No migration is applied. Commits synthetic fixtures.
-- Invoke through race-driver.py with an explicit local disposable connection and
-- both authorization flags. A fresh, already-migrated cc_qa_* DB is required PER case.
-- fixture.sql must be regenerated by generate.ts after the engineInput source fix.
-- No fabricated application approvals/bindings, ordinary enrollment or bank promotion.
\set ON_ERROR_STOP on
\if :{?race_fixture_seed_authorized}
\else
 \echo 'NOT_RUN: explicit race_fixture_seed_authorized=true required'
 \quit 3
\endif
\if :race_fixture_seed_authorized
\else
 \quit 3
\endif
begin;
reset role;
select set_config('cc_qa.database', :'race_dbname', true) as seed_database,
 set_config('cc_qa.case', :'race_case', true) as seed_case,
 set_config('cc_qa.tag', :'race_fixture_tag', true) as seed_tag,
 set_config('cc_qa.marker', :'race_disposable_marker', true) as seed_marker \gset
do $$ begin
 if current_database()<>current_setting('cc_qa.database') or current_database()!~'^cc_qa_[a-z0-9_]+$'
  or current_setting('cc_qa.marker')<>'CARD_CLOUD_RACE_DISPOSABLE_V1'
  or (inet_server_addr() is not null and inet_server_addr() not in ('127.0.0.1'::inet,'::1'::inet))
 then raise exception 'fixture setup refused: explicit local disposable DB marker/name required'; end if;
 if current_setting('cc_qa.case') not in ('tap','claim','maintenance','flag-write')
  or current_setting('cc_qa.tag')!~'^card-cloud-race-[0-9a-f]{32}$'
 then raise exception 'fixture setup refused: invalid case or generated tag'; end if;
 if to_regnamespace('card_cloud_qa') is not null then
  raise exception 'fixture setup refused: QA schema already exists; use a fresh disposable DB'; end if;
 if to_regprocedure('public.career_apply_message_cloud_card_show_as(uuid,uuid,jsonb)') is null then
  raise exception 'fixture prerequisite missing: reviewed bridge must already be installed'; end if;
 if exists(select 1 from auth.users) or exists(select 1 from public.profiles)
  or exists(select 1 from public.career_apply_jobs) or exists(select 1 from public.career_apply_message_cards)
  or exists(select 1 from career_message_approval_private.test_users)
  or exists(select 1 from career_message_approval_private.cloud_card_enrollments)
  or exists(select 1 from public.career_apply_cloud_gate_waivers)
 then raise exception 'fixture setup refused: database is not an empty synthetic test database'; end if;
 if exists(select 1 from public.career_cloud_settings where
  key not in ('CAREER_CLOUD_APPLY','CAREER_AGENT_SUBMIT') or value<>'off') then
  raise exception 'fixture setup refused: preexisting settings must be absent or exactly OFF'; end if;
end $$;

create schema card_cloud_qa;
revoke all on schema card_cloud_qa from public,anon,authenticated,service_role;
create table card_cloud_qa.fixture_marker (
 fixture_tag text primary key, database_name text not null, database_oid oid not null,
 marker text not null, selected_case text not null, manifest jsonb,
 created_at timestamptz not null default clock_timestamp()
);
create table card_cloud_qa.scenarios (
 case_name text primary key, owner uuid not null, card_id uuid, card_hash text,
 expected_items integer, job_id uuid, receipt jsonb, source_digest text not null
);
revoke all on card_cloud_qa.fixture_marker,card_cloud_qa.scenarios from public,anon,authenticated,service_role;
insert into card_cloud_qa.fixture_marker(fixture_tag,database_name,database_oid,marker,selected_case)
 select current_setting('cc_qa.tag'),current_database(),oid,current_setting('cc_qa.marker'),current_setting('cc_qa.case')
 from pg_database where datname=current_database();

\ir fixture.sql
create temp table cc_race_state(k text primary key,v jsonb not null);
grant all on cc_race_state to authenticated,service_role;
insert into cc_race_state values('sources',pg_temp.cc_seed_sources());
do $$ declare s jsonb; begin
 select v into strict s from cc_race_state where k='sources';
 if s->>'owner' is distinct from '00000000-0000-4000-8000-00000000cb01'
  or s->>'thread_id' is distinct from '00000000-0000-4000-8000-00000000cba1'
  or coalesce(s->>'source_digest','')!~'^[0-9a-f]{64}$' then
  raise exception 'fixture prerequisite mismatch: actual engineInput source helper contract'; end if;
end $$;
-- These two OFF rows are disposable fixture data, never a live switch change.
insert into public.career_cloud_settings(key,value) values
 ('CAREER_CLOUD_APPLY','off'),('CAREER_AGENT_SUBMIT','off') on conflict(key) do nothing;

set local role service_role;
-- Synthetic TEST eligibility only. Application permissions must come from the real tap below.
insert into career_message_approval_private.test_users(user_id,enabled)
 select (v->>'owner')::uuid,true from cc_race_state where k='sources';
insert into cc_race_state
 select 'optin',public.career_apply_cloud_optin_as((v->>'owner')::uuid,true,
  'SYNTHETIC local disposable concurrency fixture; no employer or worker is invoked')
 from cc_race_state where k='sources';
insert into public.career_apply_cloud_gate_waivers(user_id,portal,max_sends,expires_at,note)
 select (v->>'owner')::uuid,'lever',1,clock_timestamp()+interval '1 hour',
 'SYNTHETIC local disposable race fixture; one claim, no engine/effect'
 from cc_race_state where k='sources' and current_setting('cc_qa.case') in ('claim','maintenance');

-- Each complete P comes from actual engineInput -> trustedFacts/planner -> prepare.
-- cc_full_item is called once per item, BEFORE show; its Hq and P stay together.
insert into cc_race_state
 select 'tap',public.career_apply_message_cloud_card_show_as((v->>'owner')::uuid,(v->>'thread_id')::uuid,
  jsonb_build_array(pg_temp.cc_full_item('tap-race'),pg_temp.cc_full_item('atomic-first')))
 from cc_race_state where k='sources';
insert into cc_race_state
 select 'claim',public.career_apply_message_cloud_card_show_as((v->>'owner')::uuid,(v->>'thread_id')::uuid,
  jsonb_build_array(pg_temp.cc_full_item('claim-race')))
 from cc_race_state where k='sources';
insert into cc_race_state
 select 'maintenance',public.career_apply_message_cloud_card_show_as((v->>'owner')::uuid,(v->>'thread_id')::uuid,
  jsonb_build_array(pg_temp.cc_full_item('maintenance')))
 from cc_race_state where k='sources';
reset role;
select set_config('request.jwt.claim.sub',(v->>'owner'),true) as fixture_sub,
 set_config('request.jwt.claims',jsonb_build_object('sub',v->>'owner','role','authenticated')::text,true) as fixture_claims
 from cc_race_state where k='sources' \gset
set local role authenticated;
insert into cc_race_state
 select 'receipt',public.career_apply_message_card_approve_own((v->>'id')::uuid,v->>'hash')
 from cc_race_state where k=current_setting('cc_qa.case') and k in ('claim','maintenance');
reset role;

insert into card_cloud_qa.scenarios(case_name,owner,card_id,card_hash,expected_items,job_id,receipt,source_digest)
 select c.k,(s.v->>'owner')::uuid,(c.v->>'id')::uuid,c.v->>'hash',jsonb_array_length(c.v#>'{payload,items}'),
 case when c.k=current_setting('cc_qa.case') then (r.v#>>'{jobs,0,id}')::uuid end,
 case when c.k=current_setting('cc_qa.case') then r.v end,s.v->>'source_digest'
 from cc_race_state c cross join cc_race_state s left join cc_race_state r on r.k='receipt'
 where c.k in ('tap','claim','maintenance') and s.k='sources';
insert into card_cloud_qa.scenarios(case_name,owner,source_digest)
 select 'flag-write',(v->>'owner')::uuid,v->>'source_digest' from cc_race_state where k='sources';
do $$ declare chosen text:=current_setting('cc_qa.case'); n integer; begin
 select count(*) into n from public.career_apply_jobs;
 if n<>case when chosen in ('claim','maintenance') then 1 else 0 end then
  raise exception 'fixture setup failed: expected exactly selected synthetic queued job'; end if;
 if exists(select 1 from public.career_apply_jobs where state<>'queued' or attempts<>0 or source is not null)
  or exists(select 1 from public.career_cloud_settings where value<>'off')
  or exists(select 1 from career_message_approval_private.cloud_card_enrollments)
 then raise exception 'fixture setup failed: seed must leave switches OFF, attempts zero and no ordinary enrollment'; end if;
 if exists(select 1 from card_cloud_qa.scenarios where case_name='tap' and
  (job_id is not null or receipt is not null)) then raise exception 'tap race card must remain open'; end if;
end $$;
update card_cloud_qa.fixture_marker set manifest=jsonb_build_object(
 'kind','card-cloud-race-seed-v1','fixture_tag',fixture_tag,'database',database_name,
 'database_oid',database_oid,'marker',marker,'selected_case',selected_case,
 'fixture_marker_table','card_cloud_qa.fixture_marker',
 'maintenance_lock_key',hashtextextended('career-card-cloud-bridge-maintenance-v1',0),
 'bridge_migration','20261024130000_career_apply_card_cloud_bridge.sql',
 'switches',jsonb_build_object('CAREER_CLOUD_APPLY','off','CAREER_AGENT_SUBMIT','off'),
 'sources',(select v from cc_race_state where k='sources'),
 'scenarios',(select jsonb_object_agg(case_name,to_jsonb(s)) from card_cloud_qa.scenarios s),
 'engine_or_employer_effects',0,'cleanup','destroy this disposable database after the selected race');
commit;
select manifest from card_cloud_qa.fixture_marker;
